      {2\text{/}3}
      \end{array} \right\rbrack$, $\mathbf{u}_{2} = \left\lbrack \begin{array}{r}
      {- 2\text{/}3} \\
      {2\text{/}3} \\
      {1\text{/}3}
      \end{array} \right\rbrack$, and $W = \text{Span~}\left\{ \mathbf{u}_{1}\text{,~}\mathbf{u}_{2} \right\}$.

Let $\textbf{y} = \left\lbrack \begin{array}{r}
      7 \\
      9
      \end{array} \right\rbrack$, $\mathbf{u}_{1} = \left\lbrack \begin{array}{r}
      {1\text{/}\sqrt{10}} \\
      {- 3\text{/}\sqrt{10}}
      \end{array} \right\rbrack$, and $W = \text{Span~}\left\{ \mathbf{u}_{1}{\}.} \right.$

Let $\mathbf{u}_{1} = \left\lbrack \begin{array}{r}
      1 \\
      1 \\
      {- 2}
      \end{array} \right\rbrack$, $\mathbf{u}_{2} = \left\lbrack \begin{array}{r}
      5 \\
      {- 1} \\
      2
      \end{array} \right\rbrack$, and $\mathbf{u}_{3} = \left\lbrack \begin{array}{r}
      0 \\
      0 \\
      1
      \end{array} \right\rbrack$. Note that $\mathbf{u}_{1}$ and $\mathbf{u}_{2}$ are orthogonal but that $\mathbf{u}_{3}$ is not orthogonal to $\mathbf{u}_{1}$ or $\mathbf{u}_{2}$. It can be shown that $\mathbf{u}_{3}$ is not in the subspace $W$ spanned by $\mathbf{u}_{1}$ and $\mathbf{u}_{2}$. Use this fact to construct a nonzero vector $\mathbf{v}$ in $\text{ℝ}^{3}$ that is orthogonal to $\mathbf{u}_{1}$ and $\mathbf{u}_{2}$.
